	private static void assertAbsentFromOldNativeReader(Fixture fixture) throws IOException {
		assertNotEquals(LmdbValue.UNKNOWN_ID, fixture.id, "The newer statement must carry a real committed ID");
		assertFalse(ValueIds.isInlined(fixture.id), "This reproduction requires genuine native dictionary membership");
		assertNull(fixture.store.values.getValue(fixture.oldSnapshot, fixture.id),
				"The held native dictionary reader must genuinely predate the appended ID");
		assertEquals(LmdbValue.UNKNOWN_ID, fixture.store.values.getId(fixture.oldSnapshot, fixture.expected),
				"Lexical lookup provides the unchanged native membership control");
	}

	private static Fixture appendAfterOldReader(Shape shape, Path directory) throws Exception {
		InspectingStore store = new InspectingStore(directory.toFile());
		SailDataset oldDataset = null;
		boolean handedOff = false;
		store.init();
		try {
			commitReadyStatement(store, BASE_SUBJECT, VF.createLiteral("preexisting native dictionary value"));
			oldDataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
			ValueStore.ReadSnapshot oldSnapshot = store.values.lastPairedSnapshot;
			assertNotNull(oldSnapshot);
			assertTrue(oldSnapshot.hasStableIds());
			Value expected = shape.value();
			assertFalse(expected instanceof LmdbValue,
					"All appended writer inputs are already initialized Simple values");
			commitReadyStatement(store, APPENDED_SUBJECT, expected);
			LmdbValue escaped;
			ValueStoreRevision issuingRevision;
			try (SailDataset newerDataset = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				ValueStore.ReadSnapshot issuingSnapshot = store.values.lastPairedSnapshot;
				assertNotNull(issuingSnapshot);
				assertTrue(issuingSnapshot.hasStableIds());
				issuingRevision = issuingSnapshot.revision();
				try (CloseableIteration<? extends Statement> statements = newerDataset.getStatements(APPENDED_SUBJECT,
						PREDICATE, null)) {
					assertTrue(statements.hasNext(),
							"The committed newer Sail view must contain the appended statement");
					escaped = assertInstanceOf(LmdbValue.class, statements.next().getObject());
					assertFalse(statements.hasNext());
				}
			}
			long id = escaped.getInternalIdentity().id();
			Fixture fixture = new Fixture(store, oldDataset, oldSnapshot, issuingRevision, expected, escaped, id);
			handedOff = true;
			return fixture;
		} finally {
			if (!handedOff) {
				try {
					if (oldDataset != null) {
						oldDataset.close();
					}
				} finally {
					store.shutDown();
				}
			}
		}
	}

	private static void commitReadyStatement(LmdbStore store, IRI subject, Value object) {
		try (SailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.addStatement(subject, PREDICATE, object);
			writer.commit();
		}
	}

	private record Fixture(InspectingStore store, SailDataset oldDataset, ValueStore.ReadSnapshot oldSnapshot,
			ValueStoreRevision issuingRevision, Value expected, LmdbValue escaped, long id) implements AutoCloseable {
		@Override
		public void close() {
			try {
				oldDataset.close();
			} finally {
				store.shutDown();
			}
		}
	}

	/** Captures the real reader returned by the ordinary Sail reservation path without changing its lifecycle. */
	private static final class InspectingValueStore extends ValueStore {
		private volatile ReadSnapshot lastPairedSnapshot;
		private volatile PayloadGate payloadGate;

		private InspectingValueStore(File directory, StoreProperties properties, LmdbStoreConfig config)
				throws IOException {
			super(directory, properties, config);
		}

		@Override
		protected byte[] getData(long id) throws IOException {
			byte[] data = super.getData(id);
			PayloadGate gate = payloadGate;
			if (gate != null) {
				gate.afterPayloadRead(id, data);
			}
			return data;
		}

		@Override
		ReadSnapshotReservation reserveReadSnapshot() throws IOException {
			return new ReadSnapshotReservation(getTxnManager().reserveReadTxn(false)) {
				@Override
				synchronized ReadSnapshot start(Txn tripleTxn) throws IOException {
					ReadSnapshot snapshot = super.start(tripleTxn);
					if (tripleTxn != null) {
						lastPairedSnapshot = snapshot;
					}
					return snapshot;
				}
			};
		}
	}

	private static final class InspectingStore extends LmdbStore {
		private InspectingValueStore values;

		private InspectingStore(File directory) {
			super(directory, new LmdbStoreConfig("spoc,posc").setForceSync(true).setInlineLiterals(false));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchBasedJoinEstimatorEnabled) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketchBasedJoinEstimatorEnabled,
					(valueDirectory, valueProperties, valueConfig) -> {
						values = new InspectingValueStore(valueDirectory, valueProperties, valueConfig);
						return values;
					}, TripleStore::new);
		}
	}

	enum Shape {
		IRI_VALUE,
		BNODE_VALUE,
		TYPED_LITERAL,
		DIRECTIONAL_LITERAL,
		TRIPLE_TERM,
		NESTED_TRIPLE_TERM;

		Value value() {
			IRI innerSubject = VF.createIRI("urn:shared-epoch:inner-subject");
			IRI innerPredicate = VF.createIRI("urn:shared-epoch:inner-predicate");
			IRI datatype = VF.createIRI("urn:shared-epoch:appended-datatype");
			Literal literal = VF.createLiteral("later appended native literal payload", datatype);
			return switch (this) {
			case IRI_VALUE -> VF.createIRI("urn:shared-epoch:appended-iri");
			case BNODE_VALUE -> VF.createBNode("later-appended-bnode");
			case TYPED_LITERAL -> literal;
			case DIRECTIONAL_LITERAL -> VF.createLiteral("later directional native literal payload", "en",
					Literal.BaseDirection.LTR);
			case TRIPLE_TERM -> VF.createTripleTerm(innerSubject, innerPredicate, literal);
			case NESTED_TRIPLE_TERM -> VF.createTripleTerm(innerSubject, innerPredicate,
					VF.createTripleTerm(VF.createBNode("later-nested-bnode"), innerPredicate, literal));
			};
		}
	}
